#[cfg(test)]
mod cancel_reject_tests {
    use super::*;
    use bytes::BytesMut;

    #[test]
    fn test_cancel_reject_codec() {
        let mut original = CancelReject {
            req_id: 123456789,
            channel_id: 1234,
            adapter: 42,
            account: "a".repeat(16),
            cl_ord_id: "a".repeat(16),
            orig_cl_ord_id: "a".repeat(16),
            reason_code: 1234,
            text: "a".repeat(32),
            ts_ns: 123456789,
            raw_ref: 123456789,
        };

        let mut buf = BytesMut::new();
        original.encode(&mut buf);
        let bytes = buf.freeze();
        assert!(CancelRejectRef::from_slice(&bytes).is_some());
        let mut reuse_bytes = bytes.clone();
        let mut reused = original.clone();
        CancelReject::decode_into(&mut reuse_bytes, &mut reused).unwrap();
        let mut bytes = bytes;

        let decoded = CancelReject::decode(&mut bytes).unwrap();
        assert_eq!(original, decoded);
        assert_eq!(original, reused);
    }
}

